77	                {item.whenLabel}
78	              </StatusBadge>
79	              <span className="text-base font-bold text-ink">
80	                {t("account.bookingSummary", {
81	                  name: item.providerName,
82	                  minutes: item.blockMinutes,
83	                })}
84	              </span>
85	            </div>
86	            <div className="flex flex-wrap items-center gap-2">
87	              <Link href={`/session/${item.id}`} className="rounded-btn">
88	                <Button icon={Phone}>{t("account.join")}</Button>
89	              </Link>
90	              {/* Reschedule/Cancel only apply to a not-yet-started booking. */}
91	              {item.status === "confirmed" ? (
92	                <>
93	                  <Button
94	                    variant="ghost"
95	                    icon={CalendarClock}
96	                    onClick={() => {
97	                      setConfirmId(null);
98	                      setRescheduleId(rescheduleId === item.id ? null : item.id);
99	                    }}
100	                  >
101	                    {t("account.reschedule")}
102	                  </Button>
103	                  <Button
104	                    variant="ghost"
105	                    icon={X}
106	                    onClick={() => {
107	                      setRescheduleId(null);
108	                      setConfirmId(item.id);
109	                    }}
110	                    disabled={pending}
111	                  >
112	                    {t("account.cancel")}
113	                  </Button>
114	                </>
115	              ) : null}
116	            </div>
117	          </div>
118	
119	          {confirmId === item.id ? (
120	            <div
121	              role="group"
122	              aria-label={t("account.cancelConfirm")}
123	              className="flex flex-wrap items-center gap-3 border-t border-border pt-3"
124	            >
125	              <span className="text-base font-bold text-ink">
126	                {t("account.cancelConfirm")}
127	              </span>
128	              <Button
129	                variant="danger"
130	                icon={X}
131	                onClick={() => cancel(item.id)}
132	                disabled={pending}
133	              >
134	                {t("account.confirmCancel")}
135	              </Button>
136	              <Button variant="ghost" onClick={() => setConfirmId(null)}>
137	                {t("account.keepBooking")}
138	              </Button>
139	            </div>
140	          ) : null}
141	
142	          {rescheduleId === item.id ? (
143	            <div className="flex flex-wrap items-end gap-3 border-t border-border pt-3">
144	              <Field label={t("account.rescheduleHeading")}>
145	                {(p) => (
146	                  <Input
147	                    {...p}
148	                    type="datetime-local"
149	                    value={newTime}
150	                    onChange={(e) => setNewTime(e.target.value)}
151	                  />
152	                )}
153	              </Field>
154	              <Button
155	                icon={Check}
156	                onClick={() => saveReschedule(item.id)}
157	                disabled={pending || !newTime}
158	              >
159	                {t("account.rescheduleSave")}
160	              </Button>
161	            </div>
162	          ) : null}
163	        </Card>
164	      ))}
165	    </ul>
166	  );
167	}
