353	export async function listProviderBookings(
354	  providerId: string,
355	): Promise<BookingRow[]> {
356	  const supabase = await createClient();
357	  const { data, error } = await supabase
358	    .from("bookings")
359	    .select("*")
360	    .eq("provider_id", providerId)
361	    .order("created_at", { ascending: false });
362	  if (error) throw error;
363	  return data ?? [];
364	}
